{
  "name": "tenants.set-tenant-configuration",
  "kind": "write",
  "description": "Create or overwrite one configuration setting, a key with a string value, on an active tenant. Allowed for a global administrator or a TenantOwner of the tenant. A tenant holds at most 100 keys, so adding a new key beyond that is rejected while overwriting an existing key still works; setting a key to the value it already has changes nothing. Every tenant member can read the values, so do not store secrets.",
  "schema": {
    "type": "object",
    "properties": {
      "TenantId": {
        "type": "string",
        "description": "Identifier of the tenant to configure."
      },
      "Key": {
        "type": "string",
        "description": "Configuration key, at most 256 characters, case-sensitive. An existing key is overwritten."
      },
      "Value": {
        "type": "string",
        "description": "Configuration value, at most 1024 characters; an empty string is allowed."
      }
    },
    "required": [
      "TenantId",
      "Key",
      "Value"
    ],
    "additionalProperties": false
  },
  "example": {
    "TenantId": "acme",
    "Key": "billing.plan",
    "Value": "enterprise"
  },
  "envelope": {
    "fixedTenant": "system",
    "aggregateIdRequired": false,
    "idempotencyKeyRequired": false,
    "arguments": [
      "aggregateId",
      "correlationId",
      "idempotencyKey",
      "extensions"
    ]
  },
  "lintFindings": [],
  "submittable": false,
  "reason": "configuration_invalid"
}
